using Microsoft.Xna.Framework;
using System.Text.Json;
namespace StarlightSyndicateDemo;
internal static class ShipBatch25Tests
{
 public static void Run()
 {
  int checks=0;void Check(bool b,string label){if(!b)throw new Exception("BATCH25 FAIL: "+label);checks++;}bool Near(double a,double b)=>Math.Abs(a-b)<.001;
  Check(ShipBatch21.AdvancedFrigates.Length==40&&FleetCatalog.Playable.Length==400,"40 new / 327 playable");
  var world=new DemoWorld();world.NewGame(0);world.Credits=10000000;
  foreach(var p in ShipBatch21.AdvancedFrigates){var h=FleetCatalog.ById[p.ShipId];world.Screen=ViewMode.Station;world.Grid="station";world.SystemId=p.HomeSystem;world.Credits=1000000;float cash=world.Credits;
   Check(world.BoardFleetHull(h.Id),"acquire "+h.Name);var ship=world.Player;Check(world.Credits==cash-(float)p.Price,"purchase debits exact price "+h.Name);
   foreach(var a in h.Attributes.Where(a=>ShipAttributeCatalog.ByKey.ContainsKey(a.Key)&&a.Key is not ("cpuLoad" or "powerLoad")))Check(Near(ship.Attributes.GetValueOrDefault(a.Key)??0,a.Value),"preserved source attribute "+h.Name+" "+a.Key);
   Check(world.TotalFitCpu<=ship.Stat("cpuOutput")+.001&&world.TotalFitPower<=ship.Stat("powerOutput")+.001,"legal CPU/grid "+h.Name);
   foreach(string bank in new[]{"high","medium","low"})Check(FittingLayoutModel.Installed(ship).Count(m=>m.Bank==bank)<=ship.Stat(bank=="high"?"hiSlots":bank=="medium"?"medSlots":"lowSlots"),"shared sockets "+h.Name+" "+bank);
   Check(world.CargoUsed<=ship.CargoMax+.001,"finite spare cargo "+h.Name);Check(ship.Drones.Sum(d=>d.Definition.Volume)<=ship.Stat("droneCapacity")&&ship.Drones.Sum(d=>d.Definition.Bandwidth)<=ship.Stat("droneBandwidth"),"legal drone bay "+h.Name);
   Check(double.IsFinite(ship.TotalDps)&&ship.TotalDps>0&&double.IsFinite(ship.EffectiveHitpoints),"finite combat stats "+h.Name);
   var gun=ship.Weapons.FirstOrDefault(s=>s.ModuleId.Length>0&&s.Definition.Kind!=WeaponKind.Bomb);Check(gun!=null,"offensive fit "+h.Name);
   world.Screen=ViewMode.Space;world.Grid="belt";ship.Position=Vector3.Zero;world.Targets=[new(){Id="victim",Kind=TargetKind.Raider,Training=true,Profile=Ship.RaiderProfile(),Position=new(1000,0,0),Signature=10000,Shield=1000000,Armor=1000000,Hull=1000000,Cap=10000}];world.SelectedId=world.LockedId="victim";world.WeaponSafety=false;
   world.Locked!.Profile!.SetStat("shieldCapacity",1000000);world.Locked.Profile.SetStat("armorHP",1000000);world.Locked.Profile.SetStat("hp",1000000);world.Locked.Profile.SetStat("signatureRadius",10000);
   world.ToggleWeapon(Array.IndexOf(ship.Weapons,gun!));Check(gun!.Active,"real gun activation "+h.Name);for(int i=0;i<750;i++)world.Update(.05f);Check(world.Locked!.Shield+world.Locked.Armor+world.Locked.Hull<3000000,"live weapon damage "+h.Name);foreach(var s in ship.Weapons)s.Stop();world.MissilesInFlight.Clear();
   if(p.Role=="Assault"){int i=Array.FindIndex(ship.Defense,s=>s.Definition?.Kind=="AssaultControl");Check(i>=0,"assault control installed "+h.Name);ship.Cap=ship.MaxCap;double resist=ship.Stat("armorThermalDamageResonance");Check(world.ToggleDefense(i)&&ship.Stat("armorThermalDamageResonance")<resist,"real assault resistance burst "+h.Name);world.UpdateDefense(ship.Defense[i].CycleLeft+.1f);Check(!ship.Defense[i].Running&&ship.Defense[i].ReactivationLeft>0,"assault burst expires / cooldown "+h.Name);}
   if(p.Role=="Interceptor"){
    Check(ship.Ewar.Any(s=>s.Definition?.Kind==EwarKind.Point),"tackle fit "+h.Name);int i=Array.FindIndex(ship.Ewar,s=>s.Definition?.Kind==EwarKind.Point);world.ToggleEwar(i);Check(ship.Ewar[i].Active,"point activates "+h.Name);world.Update(.1f);Check(world.WarpBlocked("victim"),"actual victim warp blocked "+h.Name);world.EwarEffects.Clear();ship.Ewar[i].Stop();
    if(p.Effects.Any(e=>e.System=="nullifier")){int n=Array.FindIndex(ship.Defense,s=>s.Definition?.Kind=="Nullifier");Check(n>=0,"fleet nullifier fit "+h.Name);world.EwarZones=[new(){Kind=EwarKind.Sphere,Center=ship.Position,Radius=1000,Remaining=100}];Check(world.WarpBlocked("player"),"bubble blocks before activation "+h.Name);Check(world.ToggleDefense(n)&&!world.WarpBlocked("player"),"real bubble escape "+h.Name);world.EwarEffects.Add(new(){SourceId="victim",TargetId="player",Kind=EwarKind.Point,Strength=1,Remaining=100});Check(world.WarpBlocked("player"),"targeted tackle still blocks "+h.Name);world.EwarEffects.Clear();world.UpdateDefense(ship.Defense[n].CycleLeft+.1f);Check(world.WarpBlocked("player")&&!world.ToggleDefense(n),"immunity expires and cooldown blocks "+h.Name);world.EwarZones.Clear();}
   }
   if(p.Role=="Electronic warfare"){
    int i=Array.FindIndex(ship.Ewar,s=>s.Definition?.Kind is EwarKind.Damp or EwarKind.ECM or EwarKind.Tracking or EwarKind.Paint);Check(i>=0,"EW mission fit "+h.Name);ship.Cap=ship.MaxCap;if(ship.Ewar[i].Definition!.Kind==EwarKind.ECM){var victim=world.Locked!.Profile!;victim.NativeSensor=ship.Ewar[i].Definition!.Sensor;victim.SetStat("scan"+victim.NativeSensor+"Strength",1);victim.SetStat("ECMResistance",1);}
    world.ToggleEwar(i);Check(ship.Ewar[i].Active,"EW activates "+h.Name);for(int k=0;k<500;k++){ship.Cap=ship.MaxCap;world.Update(.1f);}var ew=world.EwarFor("victim");Check(world.EwarEffects.Any(e=>e.TargetId=="victim")||ew.LockRange<1||ew.Tracking<1||ew.Signature>1,"live EW reaches victim "+h.Name);world.EwarEffects.Clear();foreach(var e in ship.Ewar)e.Stop();
   }
   if(p.Role=="Bomber"){
    Check(gun!.Definition.Family=="Missile Launcher Torpedo","oversized torpedo starter "+h.Name);int cloak=Array.FindIndex(ship.Special,s=>s.Definition?.Kind=="CovertCloak");Check(cloak>=0,"covert cloak fit "+h.Name);world.Targets.Clear();world.SelectedId=world.LockedId="";Check(world.ToggleSpecial(cloak)&&world.Cloaked&&!world.WarpBlocked("player"),"covert warp "+h.Name);world.ToggleWeapon(Array.IndexOf(ship.Weapons,gun));Check(!gun.Active,"cloak blocks firing "+h.Name);world.ToggleSpecial(cloak);Check(world.SpecialLockRecovery==0&&Near(ship.Special[cloak].Cooldown,15),"instant target recovery / 15s cloak cooldown "+h.Name);
    world.SystemId="rook";world.Targets=[new(){Id="bombvictim",Kind=TargetKind.Raider,Training=true,Profile=Ship.RaiderProfile(),Position=new(15300,0,0),Signature=10000,Shield=100000,Armor=100000,Hull=100000}];world.Targets[0].Profile!.SetStat("signatureRadius",10000);world.Targets[0].Profile!.SetStat("shieldCapacity",100000);world.SelectedId="bombvictim";int bomb=Array.FindIndex(ship.Weapons,s=>s.ModuleId.Length>0&&s.Definition.Kind==WeaponKind.Bomb);Check(bomb>=0,"bomb rack fit "+h.Name);int loaded=ship.Weapons[bomb].Loaded;world.ToggleWeapon(bomb);Check(ship.Weapons[bomb].Active,"unguided bomb activation "+h.Name);for(int k=0;k<210;k++)world.Update(.05f);Check(ship.Weapons[bomb].Loaded==loaded-1&&world.Targets[0].Shield<100000,"real bomb consumes charge and damages "+h.Name);
    world.Screen=ViewMode.Station;int empty=Array.FindIndex(ship.Weapons,s=>s.ModuleId.Length==0);if(empty>=0)Check(world.FitError(ship.Weapons[bomb].Definition,empty).Length>0,"second bomb rack rejected "+h.Name);
   }
   world.Screen=ViewMode.Station;world.Targets.Clear();world.MissilesInFlight.Clear();world.EwarEffects.Clear();world.EwarZones.Clear();Console.WriteLine("BATCH25 PASS: "+h.Faction+" / "+h.Name+" / "+p.Role);
  }
  Ship Hull(string name,int level=5){var s=new Ship();s.ApplyFleetHull(FleetCatalog.Source(name));foreach(int skill in ShipBatch21.ById[s.CombatHull].Traits.Where(t=>t.Skill!=0).Select(t=>t.Skill).Distinct())s.HullProficiency[skill]=level;return s;}
  var hybrid=WeaponCatalog.All.First(w=>w.Size==1&&w.Family=="Railguns");var torpedo=WeaponCatalog.All.First(w=>w.Family=="Missile Launcher Torpedo");var bombDef=WeaponCatalog.All.First(w=>w.Kind==WeaponKind.Bomb);var missile=WeaponCatalog.All.First(w=>w.Size==1&&w.Family=="Missile Launcher Light");
  Check(Near(Hull("Enyo").HullWeapon(hybrid,"damage"),1.5)&&Near(Hull("Enyo").HullWeapon(hybrid,"tracking"),1.375)&&Near(Hull("Enyo").HullWeapon(hybrid,"optimal"),1.5),"Enyo independent V damage / tracking / range");
  Check(Near(Hull("Ares").HullFactor("prop","signature","MWD"),.25)&&Near(Hull("Ares").NullifierFactor("reactivation"),.2)&&Near(Hull("Ares").NullifierFactor("duration"),2),"Ares V MWD and role nullifier factors");
  Check(Near(Hull("Whiptail").NullifierFactor("scanPenalty"),1)&&Near(Hull("Ares").NullifierFactor("scanPenalty"),.2),"rare interceptor scan penalty differs from fleet interceptor");
  Check(Near(Hull("Nemesis").HullWeapon(torpedo,"power"),.0035)&&Near(Hull("Nemesis").HullWeapon(torpedo,"damage","Thermal"),1.75)&&Near(Hull("Nemesis").HullWeapon(torpedo,"damage","EM"),1)&&Near(Hull("Nemesis").HullWeapon(bombDef,"damage","Thermal"),1.25),"Nemesis independent oversized fit and typed ordnance");
  Check(Near(Hull("Manticore").HullWeapon(torpedo,"damage","Kinetic"),1.75)&&Near(Hull("Purifier").HullWeapon(torpedo,"damage","EM"),1.75)&&Near(Hull("Hound").HullWeapon(torpedo,"damage","Explosive"),1.75),"four faction torpedo damage types");
  Check(Near(Hull("Virtuoso").HullWeapon(torpedo,"cpu"),.1)&&Near(Hull("Virtuoso").HullWeapon(bombDef,"cpu"),0)&&Near(Hull("Virtuoso").HullWeapon(torpedo,"cycle"),.67),"Virtuoso role fit and rate of fire");
  var neut=EwarCatalog.All.First(d=>d.Kind==EwarKind.Neutralizer&&d.Size==1);Check(Near(Hull("Sentinel").HullEwar(neut)!.Optimal/neut.Optimal,5)&&Near(Hull("Sentinel").HullEwar(neut)!.Strength/neut.Strength,2),"Sentinel V neut drain and range");
  var paint=EwarCatalog.All.First(d=>d.Kind==EwarKind.Paint);Check(Near(Hull("Hyena").HullEwar(paint)!.Strength/paint.Strength,1.5)&&Near(Hull("Hyena").Stat("signatureRadius")/FleetCatalog.Source("Hyena").Value("signatureRadius"),.85),"Hyena independent painter and signature");
  var light=DroneCatalog.All.First(d=>!d.Fighter&&d.Kind=="Combat"&&d.Volume==5);var heavy=DroneCatalog.All.First(d=>!d.Fighter&&d.Kind=="Combat"&&d.Volume>5);Check(Near(light.Enhanced(Hull("Whiptail")).Packet.Total/light.Packet.Total,4.75)&&Near(heavy.Enhanced(Hull("Whiptail")).Packet.Total/heavy.Packet.Total,1),"Whiptail bonus only light combat drones");
  var webDrone=DroneCatalog.All.First(d=>d.Effect=="Web");var geri=webDrone.Enhanced(Hull("Geri"));Check(Near(geri.Strength/webDrone.Strength,6)&&Near(geri.Shield/webDrone.Shield,3.5)&&Near(geri.Speed/webDrone.Speed,1.5),"Geri web drone effects");
  var energy=WeaponCatalog.All.First(w=>w.Size==1&&w.Kind==WeaponKind.Entropic);Check(Near(Hull("Nergal").HullWeapon(energy,"rampMax"),2)&&Near(Hull("Nergal").HullWeapon(energy,"optimal"),1.375),"Nergal maximum ramp bonus");
  Check(Near(Hull("Shapash").HullFactor("plate","mass"),0)&&Near(Hull("Shapash").HullFactor("prop","overheat"),1.5),"Shapash plate and propulsion overheat");
  var warpCheck=new DemoWorld{Player=Hull("Ares")};Check(Near(warpCheck.WarpRate,8),"Ares actual eight AU per second role warp speed");Check(Near(warpCheck.WarpPresentationSeconds,1.5025),"Ares speed and acceleration affect presentation phases");
  var reject=new DemoWorld();reject.NewGame(0);var paid=ShipBatch21.AdvancedFrigates.First();reject.SystemId=paid.HomeSystem;reject.Credits=0;Check(!reject.BoardFleetHull(paid.ShipId)&&reject.FleetBerths.Count==0,"insufficient purchase atomic");reject.Credits=100000;reject.SystemId="rook";Check(!reject.BoardFleetHull(paid.ShipId)&&reject.FleetBerths.Count==0,"wrong station atomic");Check(reject.FitError(torpedo,0).Length>0,"non bomber cannot oversize torpedo");
  var boost=new DemoWorld();boost.NewGame(0);boost.Credits=100000;boost.SystemId="rook";Check(boost.BoardFleetHull(FleetCatalog.Source("Virtuoso").Id),"booster fixture acquisition");boost.Hangar["booster25_focus"]=2;double recharge=boost.Player.Stat("rechargeRate");Check(boost.ConsumeCombatBooster("booster25_focus")&&boost.ItemCount("booster25_focus",true)==1,"booster consumes inventory");Check(Near(boost.Player.Stat("rechargeRate")/recharge,1.075)&&!boost.ConsumeCombatBooster("booster25_focus"),"Virtuoso mitigates actual penalty and dose cannot stack");boost.Update(301);Check(Near(boost.Player.Stat("rechargeRate"),recharge)&&boost.Player.BoosterTime==0,"booster finite expiry");
  string save=Path.Combine(Path.GetTempPath(),"batch25-"+Guid.NewGuid());var previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");try{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",save);world.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.GrantedFleetHulls.Intersect(ShipBatch21.AdvancedFrigates.Select(p=>p.ShipId)).Count()==40,"all forty ownership restore");foreach(var p in ShipBatch21.AdvancedFrigates){var old=world.Player.CombatHull==p.ShipId?world.Player:world.FleetBerths.Single(b=>b.Ship.CombatHull==p.ShipId).Ship;var copy=loaded.Player.CombatHull==p.ShipId?loaded.Player:loaded.FleetBerths.Single(b=>b.Ship.CombatHull==p.ShipId).Ship;Check(old.Attributes.SequenceEqual(copy.Attributes),"saved attributes "+p.ShipId);Check(JsonSerializer.Serialize(FittingLayoutModel.Installed(old))==JsonSerializer.Serialize(FittingLayoutModel.Installed(copy)),"saved complete fits "+p.ShipId);}}
  finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",previous);if(Directory.Exists(save))Directory.Delete(save,true);}
  Console.WriteLine($"{checks} advanced frigate checks passed / 40 hulls.");
 }
}
